<span class="line"><span style="--shiki-light:#383A42;--shiki-dark:#E5C07B;">window</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">.</span><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">removeEventListener</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">(‘</span><span style="--shiki-light:#383A42;--shiki-dark:#E06C75;">scroll</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">’, </span><span style="--shiki-light:#383A42;--shiki-dark:#E06C75;">throttleFunc</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">)</span></span>
